import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { AuditLogService } from '../services/auditLog.service';

interface AuditRecordRequest {
  auditId: string;
  organizationId: string;
  userRole: string;
}

@Controller()
export class ComplianceMicroserviceController {
  constructor(private readonly auditService: AuditLogService) {}

  @MessagePattern({ role: 'compliance', action: 'view_audit_record' })
  async getAuditRecord(@Payload() data: AuditRecordRequest) {
    if (!data.organizationId) {
      return { error: 'Organization context required', status: 401 };
    }

    const record = await this.auditService.findById(data.auditId);
    if (!record) {
      return { error: 'Audit log entry not found', status: 404 };
    }

    // Verify tenant ownership and compliance officer role
    if (record.organizationId !== data.organizationId || data.userRole !== 'COMPLIANCE_OFFICER') {
      return { error: 'Access denied to cross-organization audit trails', status: 403 };
    }

    return {
      auditId: record.id,
      actorEmail: record.actorEmail,
      clientIp: record.clientIp,
      action: record.actionName,
      payloadBefore: record.payloadBefore,
      payloadAfter: record.payloadAfter
    };
  }
}
